import { test, expect, selectors, runId, demoProcessor, timeoutProcessor, input, choose, formItem, enterSamples, saveDialog, clickAndResponse, confirmDialog, fileHash } from './support.js';
import fs from 'node:fs/promises';

async function variantProof(info, caseId, variantId, actual) {
  const result={caseId,variantId,status:'PASS',testTitle:info.title,actual};
  await fs.writeFile(info.outputPath(`variant-${caseId}-${variantId}.json`),JSON.stringify(result,null,2));
  await info.attach(`${caseId}/${variantId}`,{body:JSON.stringify(result),contentType:'application/json'});
}

async function createJob(page,backend,name,processor=demoProcessor,params='success') {
  await page.goto('/#/oms/job'); await page.getByRole('button',{name:'New job',exact:true}).click();
  const dialog=selectors.dialog(page);
  await input(dialog,'Job name',name); await input(dialog,'Job params',params);
  await choose(page,dialog,'Schedule info','API'); await choose(page,dialog,'Execution config','Standalone',0); await choose(page,dialog,'Execution config','BUILT_IN',1); await input(dialog,'Execution config',processor);
  await saveDialog(page,'/job/save'); const result=(await backend.listJobs(name)).data.find(job=>job.jobName===name); expect(result).toBeTruthy(); return String(result.id);
}
async function newWorkflow(page,name) {
  await page.goto('/#/oms/workflow'); await page.getByRole('button',{name:'New workflow',exact:true}).click();
  await expect(page).toHaveURL(/workflowEditor/); await input(page.locator('main'),'Workflow name',name);
}
async function importJob(page,name,jobId) {
  await page.locator('.canvas-toolbar').getByRole('button',{name:/Import job/}).click();
  const drawer=page.getByRole('dialog').filter({visible:true}).last();
  await input(drawer,'Job ID',jobId || '');await input(drawer,'Keyword',jobId ? '' : name); await drawer.getByRole('button',{name:'Query',exact:true}).click();
  const result=await clickAndResponse(page,'/workflow/saveNode',()=>selectors.row(page,name).getByRole('button',{name:'Import',exact:true}).click());
  expect(result.success).toBe(true); await expect(drawer).not.toBeVisible();
  const id=String(result.data[0].id); await expect(page.locator(`[data-node-id="${id}"]`)).toBeVisible(); return id;
}
async function saveWorkflow(page) {
  const result=await clickAndResponse(page,'/workflow/save',()=>page.locator('.editor-heading').getByRole('button',{name:'Save',exact:true}).click());
  expect(result.success).toBe(true); await expect(page).toHaveURL(/workflowId=/); return String(result.data);
}
async function node(page,id) { return page.locator(`[data-node-id="${id}"]`); }
async function connect(page,source,target,label) {
  const start=page.locator(`[data-node-id="${source}"] ${label==='Y'?'.branch-yes':label==='N'?'.branch-no':'.output-anchor'}`);
  const end=page.locator(`[data-node-id="${target}"] .node-shape`);
  await page.locator(`[data-node-id="${source}"]`).click(); await start.hover();
  const a=await start.boundingBox(), b=await end.boundingBox();
  expect(a).toBeTruthy(); expect(b).toBeTruthy();
  await page.mouse.move(a.x+a.width/2,a.y+a.height/2); await page.mouse.down(); await page.mouse.move(b.x+b.width/2,b.y+b.height/2,{steps:12}); await page.mouse.up();
}
async function editCondition(page,id,code,paste=false) {
  await (await node(page,id)).click();
  const editor=page.locator('.node-panel .monaco-editor'); await expect(editor).toBeVisible();
  await editor.click({position:{x:100,y:30}}); await page.keyboard.press('ControlOrMeta+A');if(paste){await page.context().grantPermissions(['clipboard-read','clipboard-write']);await page.evaluate(text=>navigator.clipboard.writeText(text),code);await page.keyboard.press('ControlOrMeta+V');}else await page.keyboard.insertText(code);
  const result=await clickAndResponse(page,'/workflow/saveNode',()=>page.locator('.node-panel').getByRole('button',{name:'Save',exact:true}).click()); expect(result.success).toBe(true);
}
async function findWorkflow(page,id) {
  await page.goto('/#/oms/workflow'); await input(page.locator('main'),'Workflow ID',id); await page.getByRole('button',{name:'Query',exact:true}).click(); const row=selectors.row(page,String(id)); await expect(row).toBeVisible(); return row;
}
async function workflowInfo(backend,id) { return backend.call('/workflow/fetch?workflowId='+encodeURIComponent(id)); }
async function waitWorkflow(backend,id,statuses) {
  let info;
  await expect.poll(async()=>{info=await backend.call('/wfInstance/info?wfInstanceId='+encodeURIComponent(id));return info.status;},{timeout:60_000,intervals:[500,1000,2000]}).toBeOneOf(statuses);
  return info;
}
async function runWorkflow(page,id,parameters) {
  const row=await findWorkflow(page,id);
  if (parameters !== undefined) {
    await row.locator('.el-dropdown').hover(); await page.locator('.el-dropdown-menu:visible').getByRole('button',{name:'Run by parameter',exact:true}).click();
    await selectors.dialog(page).locator('textarea').fill(parameters);
    const result=await clickAndResponse(page,'/workflow/run',()=>selectors.dialog(page).getByRole('button',{name:'Run',exact:true}).click()); expect(result.success).toBe(true); return String(result.data);
  }
  const result=await clickAndResponse(page,'/workflow/run',()=>row.getByRole('button',{name:'Run',exact:true}).click()); expect(result.success).toBe(true); return String(result.data);
}
async function clean(backend,workflows,jobs,instances=[]) {
  for(const instance of instances) await backend.call('/wfInstance/stop?wfInstanceId='+encodeURIComponent(instance),{allowFailure:true});
  for(const id of workflows.reverse()) { const info=await workflowInfo(backend,id); if (!info.wfName.startsWith(runId)) throw new Error('Refusing cleanup of another lane workflow'); await backend.call('/workflow/delete?workflowId='+encodeURIComponent(id)); }
  for(const id of jobs) await backend.deleteOwnedJob(id);
}

