    await editCondition(page,condition,'return true');
    await connect(page,condition,first,'Y'); await connect(page,condition,second,'N'); await expect(page.locator('.dag-edge')).toHaveCount(2);
    await connect(page,first,condition); await expect(page.locator('.dag-edge')).toHaveCount(2); await expect(page.locator('.el-message--warning').last()).toContainText(/cycles|循环/);
