test('UI-021/034 · conditional branch reconnection and native Monaco JSON/JavaScript/Groovy mode round trips',async({page,backend,credentials},testInfo)=>{
  test.setTimeout(150_000);await enterSamples(page,credentials);const jobs=[],workflows=[];
  try {
    const jobName=`${runId}_workflow_language_job`;jobs.push(await createJob(page,backend,jobName));await newWorkflow(page,`${runId}_workflow_languages`);const a=await importJob(page,jobName),b=await importJob(page,jobName),replacement=await importJob(page,jobName);const control=await clickAndResponse(page,'/workflow/saveNode',()=>page.locator('.canvas-toolbar').getByRole('button',{name:/Condition/}).click());const condition=String(control.data[0].id);await editCondition(page,condition,'return true');await connect(page,condition,a,'Y');await connect(page,condition,b,'N');await connect(page,condition,replacement,'Y');await expect(page.locator('.dag-edge')).toHaveCount(2);
    await page.locator('.dag-edge').filter({has:page.locator('.branch-label',{hasText:'Y'})}).locator('.edge-hit').click({force:true});await page.locator('.canvas-toolbar').getByRole('button',{name:'Delete',exact:true}).click();await expect(page.locator('.dag-edge')).toHaveCount(1);await connect(page,condition,replacement,'Y');await expect(page.locator('.dag-edge')).toHaveCount(2);const id=await saveWorkflow(page);workflows.push(id);const graph=await workflowInfo(backend,id);expect(graph.peworkflowDAG.edges.find(edge=>String(edge.to)===replacement).property).toBe('true');expect(graph.peworkflowDAG.edges.find(edge=>String(edge.to)===b).property).toBe('false');expect(graph.peworkflowDAG.edges.some(edge=>String(edge.to)===a)).toBe(false);
    await (await node(page,condition)).click();await page.locator('.node-panel .code-toolbar .el-select').click();await page.getByRole('option',{name:'JSON',exact:true}).click();const json='{"message":"中文😀",\n "quote":"\\\"", "line":"first\\nsecond"}';await editCondition(page,condition,json,true);expect((await workflowInfo(backend,id)).peworkflowDAG.nodes.find(current=>String(current.nodeId)===condition).nodeParams).toBe(json);
    await page.locator('.node-panel .code-toolbar .el-select').click();await page.getByRole('option',{name:'JavaScript',exact:true}).click();await clickAndResponse(page,'/workflow/saveNode',()=>page.locator('.node-panel').getByRole('button',{name:'Save',exact:true}).click());expect((await workflowInfo(backend,id)).peworkflowDAG.nodes.find(current=>String(current.nodeId)===condition).nodeParams).toBe(json);await editCondition(page,condition,'return true');await page.locator('.node-panel .code-toolbar .el-select').click();await page.getByRole('option',{name:'Groovy',exact:true}).click();await saveWorkflow(page);await page.reload();await expect(page.locator('.dag-edge')).toHaveCount(2);await (await node(page,condition)).click();await expect(page.locator('.node-panel .code-toolbar')).toContainText('Groovy');expect((await workflowInfo(backend,id)).peworkflowDAG.nodes.find(current=>String(current.nodeId)===condition).nodeParams).toBe('return true');
    await testInfo.attach('monaco-and-reconnection',{body:JSON.stringify({workflowId:id,condition,removedYTarget:a,newYTarget:replacement,unchangedNTarget:b,persistedEdges:graph.peworkflowDAG.edges,jsonRoundTrip:json,languageSwitchDidNotTransformCode:true,restoredExecutableGroovy:'return true'}),contentType:'application/json'});
  } finally {await clean(backend,workflows,jobs);}
});


test('UI-024 · Workflow instance list cancel/confirm stop, failed retry and successful recovery',async({page,backend,credentials},info)=>{
  test.setTimeout(240_000);await enterSamples(page,credentials);const jobs=[],workflows=[],instances=[];
  async function listRow(id){await page.goto('/#/oms/wfinstance');await input(page.locator('main'),'WorkflowInstanceId',id);await clickAndResponse(page,'/wfInstance/list',()=>page.getByRole('button',{name:'Query',exact:true}).click());const row=selectors.row(page,String(id));await expect(row).toBeVisible();return row;}
  try {
    const slowName=`${runId}_list_slow`;jobs.push(await createJob(page,backend,slowName,timeoutProcessor,'30000'));await newWorkflow(page,`${runId}_list_stop`);await importJob(page,slowName);const slowId=await saveWorkflow(page);workflows.push(slowId);const slow=await runWorkflow(page,slowId);instances.push(slow);await waitWorkflow(backend,slow,[2]);let row=await listRow(slow);await expect(row).toContainText('Running');let stopRequests=0;const observe=request=>{if(request.url().split('?')[0].endsWith('/wfInstance/stop'))stopRequests++;};page.on('request',observe);await row.getByRole('button',{name:'Stop',exact:true}).click();await confirmDialog(page,false);expect(stopRequests).toBe(0);expect((await backend.call('/wfInstance/info?wfInstanceId='+slow)).status).toBe(2);await variantProof(info,'UI-024','wfinstance-stop-cancel',{wfInstanceId:slow,realListButton:true,zeroRequests:stopRequests,independentStatus:2});
    await row.getByRole('button',{name:'Stop',exact:true}).click();const stopped=await clickAndResponse(page,'/wfInstance/stop',()=>confirmDialog(page));expect(stopped.success).toBe(true);await waitWorkflow(backend,slow,[10]);await clickAndResponse(page,'/wfInstance/list',()=>page.getByRole('button',{name:'Refresh',exact:true}).click());await expect(selectors.row(page,slow)).toContainText('Stopped');page.off('request',observe);await variantProof(info,'UI-024','wfinstance-stop',{wfInstanceId:slow,confirmedActualListButton:true,status:10});
    const failedName=`${runId}_list_failed`;const job=await createJob(page,backend,failedName,demoProcessor,'failed');jobs.push(job);const nextName=`${runId}_list_next`;jobs.push(await createJob(page,backend,nextName));await newWorkflow(page,`${runId}_list_retry`);const failedNode=await importJob(page,failedName),nextNode=await importJob(page,nextName);await connect(page,failedNode,nextNode);const id=await saveWorkflow(page);workflows.push(id);const failed=await runWorkflow(page,id);instances.push(failed);const before=await waitWorkflow(backend,failed,[3]);row=await listRow(failed);await expect(row).toContainText('Failed');const retryFailed=await clickAndResponse(page,'/wfInstance/retry',()=>row.getByRole('button',{name:'Retry',exact:true}).click());expect(retryFailed.success).toBe(true);const again=await waitWorkflow(backend,failed,[3]);expect(String(again.peworkflowDAG.nodes[0].instanceId)).not.toBe(String(before.peworkflowDAG.nodes[0].instanceId));await clickAndResponse(page,'/wfInstance/list',()=>page.getByRole('button',{name:'Refresh',exact:true}).click());await expect(selectors.row(page,failed)).toContainText('Failed');
    await page.goto('/#/oms/wfInstanceDetail?wfInstanceId='+failed);await (await node(page,failedNode)).click();const marked=await clickAndResponse(page,'/wfInstance/markNodeAsSuccess',()=>page.locator('.canvas-toolbar').getByRole('button',{name:'Marked Success',exact:true}).click());expect(marked.success).toBe(true);const failedChild=String(again.peworkflowDAG.nodes.find(n=>String(n.nodeId)===failedNode).instanceId);expect((await backend.call('/instance/detailPlus',{method:'POST',data:{instanceId:failedChild}})).status).toBe(4);row=await listRow(failed);const retrySuccess=await clickAndResponse(page,'/wfInstance/retry',()=>row.getByRole('button',{name:'Retry',exact:true}).click());expect(retrySuccess.success).toBe(true);const recovered=await waitWorkflow(backend,failed,[4]);const succeeded=recovered.peworkflowDAG.nodes.find(n=>String(n.nodeId)===nextNode);expect(succeeded.status).toBe(5);expect((await backend.call('/instance/detailPlus',{method:'POST',data:{instanceId:String(succeeded.instanceId)}})).status).toBe(5);await clickAndResponse(page,'/wfInstance/list',()=>page.getByRole('button',{name:'Refresh',exact:true}).click());await expect(selectors.row(page,failed)).toContainText('Success');await variantProof(info,'UI-024','wfinstance-retry',{wfInstanceId:failed,originalChildInstanceId:before.peworkflowDAG.nodes.find(n=>String(n.nodeId)===failedNode).instanceId,retriedFailedChildInstanceId:failedChild,recoveredSuccessorChildInstanceId:succeeded.instanceId,actualListRetryTwice:true,failureStillVisible:true,originalFailedChildStillFailed:true,failedNodeMarkedThroughActualDetailToolbar:true,successorExecutedByRealWorker:true,finalSuccess:4});
  } finally {await clean(backend,workflows,jobs,instances);}
});


