test('UI-025/038 · stale network failures and stop confirmations cannot change the new workflow route target',async({page,backend,credentials},info)=>{
  test.setTimeout(180_000);await enterSamples(page,credentials);const jobs=[],workflows=[],instances=[],held=[],stops=[];
  async function holdOriginalAndAbort(path,idKey,id){let ready,release,done;const pending=new Promise(resolve=>{ready=resolve;}),gate=new Promise(resolve=>{release=resolve;}),finished=new Promise(resolve=>{done=resolve;});const observation={path,id:String(id),forwardedOriginalServer:false,networkAborted:false};await page.route('**'+path+'?**',async route=>{expect(new URL(route.request().url()).searchParams.get(idKey)).toBe(String(id));const response=await route.fetch();expect(response.ok()).toBe(true);observation.forwardedOriginalServer=true;ready();await gate;await route.abort('failed');observation.networkAborted=true;done();},{times:1});const value={pending,release,finished,observation};held.push(value);return value;}
  const observe=request=>{if(request.url().split('?')[0].endsWith('/wfInstance/stop'))stops.push(new URL(request.url()).searchParams.get('wfInstanceId'));};page.on('request',observe);
  try{
    const jobName=`${runId}_route_context_slow`;jobs.push(await createJob(page,backend,jobName,timeoutProcessor,'120000'));await newWorkflow(page,`${runId}_route_context_a`);await importJob(page,jobName);const workflowA=await saveWorkflow(page);workflows.push(workflowA);await newWorkflow(page,`${runId}_route_context_b`);await importJob(page,jobName);const workflowB=await saveWorkflow(page);workflows.push(workflowB);const instanceA=await runWorkflow(page,workflowA),instanceB=await runWorkflow(page,workflowB);instances.push(instanceA,instanceB);await waitWorkflow(backend,instanceA,[2]);await waitWorkflow(backend,instanceB,[2]);
    const oldEditor=await holdOriginalAndAbort('/workflow/fetch','workflowId',workflowA);await page.goto('/#/oms/workflowEditor?workflowId='+workflowA);await oldEditor.pending;await page.evaluate(id=>{location.hash='/oms/workflowEditor?workflowId='+id;},workflowB);await expect(page.locator('.editor-heading')).toContainText(`${runId}_route_context_b`);oldEditor.release();await oldEditor.finished;await page.waitForTimeout(1500);await expect(page).toHaveURL(new RegExp('workflowEditor\\?workflowId='+workflowB+'$'));await expect(page.locator('.editor-heading')).toContainText(`${runId}_route_context_b`);await expect(page.locator('.dag-node')).toHaveCount(1);
    const oldDetail=await holdOriginalAndAbort('/wfInstance/info','wfInstanceId',instanceA);await page.goto('/#/oms/wfInstanceDetail?wfInstanceId='+instanceA);await oldDetail.pending;await page.evaluate(id=>{location.hash='/oms/wfInstanceDetail?wfInstanceId='+id;},instanceB);await expect(page.locator('.instance-heading')).toContainText(instanceB);oldDetail.release();await oldDetail.finished;await page.waitForTimeout(1500);await expect(page).toHaveURL(new RegExp('wfInstanceDetail\\?wfInstanceId='+instanceB+'$'));await expect(page.locator('.instance-heading')).toContainText(instanceB);await expect(page.locator('.instance-summary')).toContainText('Running');
    await page.evaluate(id=>{location.hash='/oms/wfInstanceDetail?wfInstanceId='+id;},instanceA);await expect(page.locator('.instance-heading')).toContainText(instanceA);await page.locator('.instance-actions').getByRole('button',{name:'Stop',exact:true}).click();await expect(page.locator('.el-message-box')).toContainText(instanceA);await page.evaluate(id=>{location.hash='/oms/wfInstanceDetail?wfInstanceId='+id;},instanceB);await expect(page.locator('.instance-heading')).toContainText(instanceB);await expect(selectors.confirm(page)).not.toBeVisible();expect(stops).toEqual([]);await page.evaluate(async id=>{await document.querySelector('#app').__vue_app__.config.globalProperties.$router.push({name:'WorkflowInstanceDetail',query:{wfInstanceId:id}});},instanceA);await expect(page.locator('.instance-heading')).toContainText(instanceA);await page.locator('.instance-actions').getByRole('button',{name:'Stop',exact:true}).click();await expect(selectors.confirm(page)).toContainText(instanceA);await page.evaluate(async id=>{await document.querySelector('#app').__vue_app__.config.globalProperties.$router.push({name:'WorkflowInstanceDetail',query:{wfInstanceId:id}});},instanceB);await expect(page.locator('.instance-heading')).toContainText(instanceB);await expect(selectors.confirm(page)).toBeVisible();await expect(selectors.confirm(page)).toContainText(instanceA);await confirmDialog(page);await page.waitForTimeout(1000);expect(stops).toEqual([]);const stillA=await waitWorkflow(backend,instanceA,[2]),stillB=await waitWorkflow(backend,instanceB,[2]);await expect(page).toHaveURL(new RegExp('wfInstanceDetail\\?wfInstanceId='+instanceB+'$'));
    await page.locator('.instance-actions').getByRole('button',{name:'Stop',exact:true}).click();await expect(page.locator('.el-message-box')).toContainText(instanceB);const result=await clickAndResponse(page,'/wfInstance/stop',()=>confirmDialog(page));expect(result.success).toBe(true);await waitWorkflow(backend,instanceB,[10]);expect(stops).toEqual([instanceB]);expect((await waitWorkflow(backend,instanceA,[2])).status).toBe(2);
    const evidence={status:'PASS',testTitle:info.title,evidenceLayers:{staleNetworkResponse:'Real browser hash navigation and actual forwarded original Server request aborted at network layer',nativeHashConfirmation:'Real browser hash navigation automatically cancels ElementPlus confirmation with zero stop requests',programmaticRouteConfirmation:'Browser component/router integration fixture invokes the existing Vue Router push method; not claimed as a clickable user route action'},workflowA,workflowB,instanceA,instanceB,oldOriginalRequests:held.map(value=>value.observation),oldEditorErrorDidNotRedirectNewEditor:true,oldDetailErrorDidNotRedirectNewDetail:true,expiredStopConfirmationRequests:0,nativeHashChangeCanceledConfirmation:true,sameComponentVueRouterChangeExpiredConfirmation:true,independentStatusesAfterExpiredConfirmation:{a:stillA.status,b:stillB.status},freshStopRequestedOnlyCurrentInstance:stops,oldInstanceStillRunning:true};await fs.writeFile(info.outputPath('workflow-route-context-guard.json'),JSON.stringify(evidence,null,2));await info.attach('workflow-route-context-guard',{body:JSON.stringify(evidence),contentType:'application/json'});
  }finally{for(const value of held)value.release();await page.unrouteAll({behavior:'wait'});page.off('request',observe);await clean(backend,workflows,jobs,instances);}
});
